%{
Tutorial on polarisation and Jones Calculus
Description:
Tutorial on polarisation and Jones Calculus, includes animator and plotters
for visualising polarisaiton states.

% Hint: To get Matlab working from same director as this script press the
'Run' button on the top bar (or F5 on your keyboard). Individual sections
(denoted by %%) can be run by pressing Command+return.
%
% If you want to disable code put a single '%' before a line of code. There
is also a comment out shortcut and button on the top bar on both Windows
and Mac.

% You shouldn't need to edit the polDisplay function at the bottom of this
script. Its just there to help you visualise what is going on. Feel free to
make your own figures as well.



Author: Andrew Wade 
Date: 26 Jun 2023

Change notes:
- 26 Jun 2023: Created
%}

% Standard preface
clear all; close all; clc;

codeversion = '20230726';

% Constants
c = 299792458; % [m/s] speed light
h = 6.626e-34; % [J.s] Planck Constant 
q = 1.602e-19; % [C] Electron Charge

% Length [m]
fm = 1e-15; pm = 1e-12; nm = 1e-9; um = 1e-6; mm = 1e-3; cm = 1e-2; km = 1e3;
in = 25.4e-3; ft = 0.3048; yd = 0.9144; ch = 20.1168; 
fur = 201.1680; mi = 1609.344; 

% Frequency [Hz]
uHz = 1e-6; mHz = 1e-3; kHz = 1e3; MHz = 1e6; GHz = 1e9;


%% Start timers, display cmd prompt metadata
tic
disp([newline newline '-------------' newline ... %[output:group:6b274e58] %[output:59a3398c]
    'Generate animation from script (ver. ' codeversion ')'... %[output:59a3398c]
    newline 'starttime = ' datestr(datetime('now'))]) %[output:group:6b274e58] %[output:59a3398c]

%% Part 1 - Visualising polariaiton states 

% Here is some example code to generate a visualisation of a vertically
% polarised state. The vector JM is a 2x1 matrix (the symbol ';' is used to
% seperate rows in MATLAB, commas ',' are used to seperate columns of
% matrices.
%
% The function polDisplay will generate a figure animation.  The function
% is at the bottom of this script.  You need to supply the function with
% number of repeats, the time for each cycle and a frame rate (see the
% function for order).  If a file name is provided it will save a gif
% animation to the current working directory.
% 
% The example below defines a Jones  matrix JM of [0; 1] which is the
% vertical state. It then calls an animation.  If you want to save the
% result then uncomment the polDisplay call with a filename included.


JM = [0; 1]; % Jones matrix, vertical polarisation
%polDisplay(JM, 5, 4, 20); % Repeat 5 times but no save file

JM = 1/sqrt(2) *[1;1]; % Jones matrix, diagonal polarisation
%polDisplay(JM, 5, 4, 20); % Repeat 5 times but no save file

theta = 45 * pi/180 %[output:2ac86e1b]
JM = [cos(theta)-sin(theta);cos(theta)+sin(theta)]; % Jones matrix, rotated polarisation
%polDisplay(JM, 5, 4, 20); % Repeat 5 times but no save file

% Save output to gif
% polDisplay(JM, 1, 4, 20, ...
%     'PolarisationLinear_vertical_hvDecomposition_animation.gif'); 



%% Part 2 - The rotated quarter wave plate
% You should perform matrix multiplication by hand to find the 2x2 matrix
% and then apply it to a linear polariation state (you can try both
% vertical and horizontal input polarisation.
%
% As a check use matlab to compute the same thing numerically.

% For rotation matrices you can either encode a matrix like
theta_exp = 45 * (pi/180); % [rad] angle converted from deg to rad
Rotation_Example = [cos(theta_exp), -sin(theta_exp); ...
                    sin(theta_exp), cos(theta_exp)];
% This matrix is populated with numerical values

% Alternatively you can use an 'anonymous' function, these function
% definitions in matlab are good for one-line functions that need to be
% defined in-line with the main script. Multi-step functions are best coded
% up in the ussual way and included at the botom of the MATLAB script or in
% a seperate .m file.

% Here is a rotation matrix implemented as a function
R = @(theta_) [cos(theta_),-sin(theta_);sin(theta_),cos(theta_)]; 

% this encoding of a rotation matrix is symbolic until you call it.  This
% is useful when you want to reuse an element like rotation many times. I
% have used a trailing underscore to indicate that its an internal
% variable; trailing underscores are not a requirment, but handing for code
% readablity.
%
% You can use R(phi) (where phi is your angle) anywhere you need a 2x2
% rotation matrix
 
% Example: rotating a horizontal polarised state by 30 deg
JM_input = [1;0]; % Input horz. pol
JM_output = R(30*(pi/180))*JM_input; % Do the transform on input

% First display input pol
%polDisplay(JM_input, 2, 4, 20); % Repeat 2 times but no save file

% Then display output
%polDisplay(JM_output, 2, 4, 20); % Repeat 2 times but no save file

% Rotated quarter wave plate at different angles

angle = 20* pi/180 %[output:4b68dfd1]
JM_qin = exp(-1i*pi/4)*[1, 0; 0, 1i] %[output:80c42e68]
JM_qout = R(angle)*JM_qin*R(angle)^-1 %[output:2fe84e56]

polDisplay(JM_qout, 2, 4, 20); % Repeat 2 times but no save file %[output:69ccac7e]
polDisplay(JM_qin, 2, 4, 20); %[output:81da8bcf]

% For the exercises perform as many matrix multiplies as you need. Reusing
% R(phi) is ok, it will update elements for each call on the function.

%% Part 3 - The circulator
% This section is more of the same.  There are more components and
% therefore more steps.  Ask questions in the workshop for help on task
% three.
%
% You may need a for loop, a solver or a minimiser to find the value of
% waveplate rotation that gets you to 1 nW of returned power.  You can also
% just manually try values. Google is your friend.



%% Closing out script
disp([newline ... %[output:group:3c351099] %[output:208cbcf9]
'Reached end script (ver. ' codeversion ')'... %[output:208cbcf9]
newline 'endtime = ' datestr(datetime('now')) [', ...' ... %[output:208cbcf9]
'Total runtime = '] num2str(toc)... %[output:208cbcf9]
 newline newline '-------------' newline]) %[output:group:3c351099] %[output:208cbcf9]


%% Functions
% Below is a function for generating animations of polarisation
function h = polDisplay(JM, nRepeats, cycleLength, frameRate, fileName)

% Input handling, establish default values
if (~exist('nRepeats', 'var')); nRepeats = 1; end % Default to display only
if (~exist('cycleLength', 'var')); cycleLength = 4.0; end % Default 4s
if (~exist('frameRate', 'var')); frameRate = 20.0; end % Default 20 fps
if (~exist('fileName', 'var')); fileName = ''; end % Default 20 fps


% Configure animation
% fileName = 'example.gif';
% frameRate = 20.0; % [Hz] Frames per second
% animationLength = 4.00; [s] length of animation
nFrames = floor(frameRate*cycleLength*nRepeats);

% Initialise time and plot line vectors, dummy values on orthogonal plane
t = linspace(0,3*2*pi,100);

% Set up plot
h = figure();
clf(h)
set(gcf,'color','w');
fp1 = plot3(t,zeros(size(t)),zeros(size(t)), 'LineWidth',2.0, 'Color','k');
fp1.XDataSource = 't';
fp1.YDataSource = 'abs(JM(1))*sin(t - ii/nFrames*2*pi*nRepeats - angle(JM(1)))';
fp1.ZDataSource = 'abs(JM(2))*sin(t - ii/nFrames*2*pi*nRepeats- angle(JM(2)))';
hold('on')

% y-axis projection and fill
fp2 = plot3(t,zeros(size(t)),zeros(size(t)), ...
    'LineWidth',1.0, 'Color', [0 0.5 0]);
fp2.XDataSource = 't';
fp2.YDataSource = 'abs(JM(2))*sin(t - ii/nFrames*2*pi*nRepeats- angle(JM(2)))';
fp2.ZDataSource = 'zeros(size(t))';
% fp2.XDataSource = 't';
% fp2.YDataSource = 'abs(JM(1))*sin(t- ii/nFrames*2*pi*nRepeats- angle(JM(1)))';
% fp2.ZDataSource = 'zeros(size(t))';

fp2_fill = fill3(t, zeros(size(t)), zeros(size(t)),[0 0.5 0], ...
    'FaceAlpha', 0.0, 'EdgeColor', 'none'); 

% x-axis projection and fill
fp3 = plot3(t,zeros(size(t)),zeros(size(t)), 'LineWidth',1.0, 'Color', 'm');
fp3.XDataSource = 't';
fp3.YDataSource = 'zeros(size(t))';
fp3.ZDataSource = 'abs(JM(2))*sin(t - ii/nFrames*2*pi*nRepeats- angle(JM(2)))';

fp3_fill = fill3(t, zeros(size(t)), zeros(size(t)), 'm', ...
    'FaceAlpha', 0.0, 'EdgeColor', 'none');


% Make vectors at end of z-axis (no arrow heads yet)
HN1 = line([t(end),t(end)], [0,0], [0,1], ...
    'LineStyle', '-', 'Color', 'm', 'LineWidth', 2.0);
HN2 = line([t(end),t(end)], [0,1], [0,0], ...
    'LineStyle', '-', 'Color', [0 0.5 0], ...
    'LineWidth', 2.0);
HNtot = line([t(end),t(end)], [0,1], [0,0], ...
    'LineStyle', '-', 'Color', 'k', 'LineWidth', 5.0);


% Set up a projection of the polarisaiton at end of the propergation plane
% polProj_x = t(end)*ones(size(t));
% polProj_y = zeros(size(t));
% polProj_z = zeros(size(t));
polPattern = plot3(t(end)*ones(size(t)), ...
    abs(JM(1))*sin(linspace(0,2*pi,100)- angle(JM(1))), ...
    abs(JM(2))*sin(linspace(0,2*pi,100) - angle(JM(2))), '-', ...
    'Color', 'k', 'LineWidth',2.0);
% polPattern.XDataSource = 't(end)*ones(size(t))';
% polPattern.YDataSource = 'polProj_y';
% polPattern.ZDataSource = 'polProj_z';

hold('off')


% Orientation and dimensioning of plot
% Moving axis to center
% See reference: https://undocumentedmatlab.com/articles/
% customizing-axes-part-5-origin-crossover-and-labels
h_axis = gca;
h_axis.XRuler.FirstCrossoverValue = 0;
h_axis.XRuler.SecondCrossoverValue = 0;
h_axis.YRuler.FirstCrossoverValue = 0;
h_axis.YRuler.SecondCrossoverValue = 0;
h_axis.ZRuler.FirstCrossoverValue = 0;
h_axis.ZRuler.SecondCrossoverValue = 0;

view(45,25)
pbaspect([2,1,1])
box('off')
ylim([-1.1,1.1])
zlim([-1.1,1.1])


% Labeling
%     title('Vertical Polarisation')
xlabel('z')
ylabel('y')
zlabel('x')

% Make animation
for ii = 0:(nFrames-1)
    % Hack manually set data as in function call doesn't seem to update
    % with source data instruction (i.e. YDataSource = '...')
    % Commented out data writes are excluded for speed, these are not
    % updated between steps.
    fp1.YData = abs(JM(1))*sin(t - ii/nFrames*2*pi*nRepeats - angle(JM(1)));
    fp1.ZData = abs(JM(2))*sin(t - ii/nFrames*2*pi*nRepeats- angle(JM(2)));

    fp2.YData = abs(JM(1))*sin(t - ii/nFrames*2*pi*nRepeats - angle(JM(1)));
%     fp2.ZData = zeros(size(t));

%     fp3.YData = zeros(size(t));
    fp3.ZData = abs(JM(2))*sin(t - ii/nFrames*2*pi*nRepeats- angle(JM(2)));



    % Fill shading and polPattern projection trace using info from above curves
    fp2_fill.XData = [0,t,t(end)]';
    fp2_fill.YData = [0,fp2.YData,0]';
    fp2_fill.ZData = [0,zeros(size(t)),0]';

    fp3_fill.XData = [0,t,t(end)]';
    fp3_fill.YData = [0,zeros(size(t)),0]';
    fp3_fill.ZData = [0,fp3.ZData,0]';

    HN1.ZData = [0,fp3.ZData(end)];
    HN2.YData = [0,fp2.YData(end)];

    HNtot.YData = [0, fp1.YData(end)];
    HNtot.ZData = [0, fp1.ZData(end)];

%     polPattern.XData = t(end)*ones(size(t));
%     polPattern.YData = fp1.YData;
%     polPattern.ZData = fp1.ZData;


    % refresh and draw
    %     refreshdata
    drawnow

    % Capture the plot as an image
    if ~isempty(fileName)
    frame = getframe(h);
    im = frame2im(frame);
    [imind,cm] = rgb2ind(im,256);
    % Write to the GIF File
    if ii == 0
        imwrite(imind,cm,fileName,'gif', ...
            'Loopcount',inf, 'DelayTime', 1/frameRate);
    else
        imwrite(imind,cm,fileName,'gif', ...
            'WriteMode','append', 'DelayTime', 1/frameRate);
    end
    else
        pause(1/frameRate)
    end

end
end

